// To enable ZGC for low-latency requirements in Java 17+
// Add these JVM arguments to your startup script:
java -XX:+UseZGC -Xms8g -Xmx8g -Xlog:gc* -jar application.jar

// To enable G1 GC with a target pause time goal:
java -XX:+UseG1GC -XX:MaxGCPauseMillis=200 -jar application.jar
